package com.example.adhar.commons.constant;

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

/**
 * Test class for {@link CommonConstants}.
 * Provides 100% test coverage for all constants in CommonConstants.
 */
class CommonConstantsTest {

    @Test
    void testHeaders() {
        // Verify all header constants
        assertEquals("X-Correlation-ID", CommonConstants.Headers.CORRELATION_ID);
        assertEquals("X-Request-ID", CommonConstants.Headers.REQUEST_ID);
        assertEquals("X-Tenant-ID", CommonConstants.Headers.TENANT_ID);
        assertEquals("X-User-ID", CommonConstants.Headers.USER_ID);
        assertEquals("X-API-Key", CommonConstants.Headers.API_KEY);
        assertEquals("Authorization", CommonConstants.Headers.AUTHORIZATION);
        assertEquals("Content-Type", CommonConstants.Headers.CONTENT_TYPE);
    }

    @Test
    void testContentTypes() {
        // Verify all content type constants
        assertEquals("application/json", CommonConstants.ContentTypes.APPLICATION_JSON);
        assertEquals("application/xml", CommonConstants.ContentTypes.APPLICATION_XML);
        assertEquals("text/plain", CommonConstants.ContentTypes.TEXT_PLAIN);
        assertEquals("text/html", CommonConstants.ContentTypes.TEXT_HTML);
        assertEquals("multipart/form-data", CommonConstants.ContentTypes.MULTIPART_FORM_DATA);
    }

    @Test
    void testDateTimeFormats() {
        // Verify all date time format constants
        assertEquals("yyyy-MM-dd", CommonConstants.DateTimeFormats.DATE);
        assertEquals("yyyy-MM-dd'T'HH:mm:ss", CommonConstants.DateTimeFormats.DATE_TIME);
        assertEquals("yyyy-MM-dd'T'HH:mm:ss.SSSXXX", CommonConstants.DateTimeFormats.DATE_TIME_WITH_ZONE);
        assertEquals("HH:mm:ss", CommonConstants.DateTimeFormats.TIME);
    }

    @Test
    void testResponseStatus() {
        // Verify all response status constants
        assertEquals("success", CommonConstants.ResponseStatus.SUCCESS);
        assertEquals("error", CommonConstants.ResponseStatus.ERROR);
        assertEquals("warning", CommonConstants.ResponseStatus.WARNING);
        assertEquals("info", CommonConstants.ResponseStatus.INFO);
    }

    @Test
    void testErrorCodes() {
        // Verify all error code constants
        assertEquals("VALIDATION_ERROR", CommonConstants.ErrorCodes.VALIDATION_ERROR);
        assertEquals("RESOURCE_NOT_FOUND", CommonConstants.ErrorCodes.RESOURCE_NOT_FOUND);
        assertEquals("SERVICE_ERROR", CommonConstants.ErrorCodes.SERVICE_ERROR);
        assertEquals("UNAUTHORIZED", CommonConstants.ErrorCodes.UNAUTHORIZED);
        assertEquals("FORBIDDEN", CommonConstants.ErrorCodes.FORBIDDEN);
        assertEquals("BAD_REQUEST", CommonConstants.ErrorCodes.BAD_REQUEST);
        assertEquals("INTERNAL_SERVER_ERROR", CommonConstants.ErrorCodes.INTERNAL_SERVER_ERROR);
    }

    @Test
    void testMdcKeys() {
        // Verify all MDC key constants
        assertEquals("correlationId", CommonConstants.MdcKeys.CORRELATION_ID);
        assertEquals("requestId", CommonConstants.MdcKeys.REQUEST_ID);
        assertEquals("tenantId", CommonConstants.MdcKeys.TENANT_ID);
        assertEquals("userId", CommonConstants.MdcKeys.USER_ID);
        assertEquals("serviceName", CommonConstants.MdcKeys.SERVICE_NAME);
        assertEquals("instanceId", CommonConstants.MdcKeys.INSTANCE_ID);
    }
}

