package com.example.adhar.commons.exception;

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

/**
 * Test class for {@link AdharException}.
 * Provides 100% test coverage for all constructors and methods in AdharException.
 */
class AdharExceptionTest {

    @Test
    void testConstructor_MessageOnly() {
        // Given
        String message = "Test error message";

        // When
        AdharException exception = new AdharException(message);

        // Then
        assertEquals(message, exception.getMessage());
        assertNull(exception.getErrorCode());
        assertNull(exception.getCause());
        assertNull(exception.getArgs());
    }

    @Test
    void testConstructor_MessageAndErrorCode() {
        // Given
        String message = "Test error message";
        String errorCode = "TEST_ERROR";

        // When
        AdharException exception = new AdharException(message, errorCode);

        // Then
        assertEquals(message, exception.getMessage());
        assertEquals(errorCode, exception.getErrorCode());
        assertNull(exception.getCause());
        assertNull(exception.getArgs());
    }

    @Test
    void testConstructor_MessageErrorCodeAndCause() {
        // Given
        String message = "Test error message";
        String errorCode = "TEST_ERROR";
        Throwable cause = new RuntimeException("Test cause");

        // When
        AdharException exception = new AdharException(message, errorCode, cause);

        // Then
        assertEquals(message, exception.getMessage());
        assertEquals(errorCode, exception.getErrorCode());
        assertEquals(cause, exception.getCause());
        assertNull(exception.getArgs());
    }

    @Test
    void testConstructor_MessageErrorCodeCauseAndArgs() {
        // Given
        String message = "Test error message";
        String errorCode = "TEST_ERROR";
        Throwable cause = new RuntimeException("Test cause");
        Object[] args = new Object[]{"arg1", 2, true};

        // When
        AdharException exception = new AdharException(message, errorCode, cause, args);

        // Then
        assertEquals(message, exception.getMessage());
        assertEquals(errorCode, exception.getErrorCode());
        assertEquals(cause, exception.getCause());
        assertNotNull(exception.getArgs());
        assertArrayEquals(args, exception.getArgs());

        // Verify that getArgs returns a clone (not the same instance)
        assertNotSame(args, exception.getArgs());
    }

    @Test
    void testGetArgs_WithNullArgs() {
        // Given
        AdharException exception = new AdharException("message", "code", null, null);

        // When & Then
        assertNull(exception.getArgs());
    }

    @Test
    void testGetArgs_WithEmptyArgs() {
        // Given
        Object[] emptyArgs = new Object[0];
        AdharException exception = new AdharException("message", "code", null, emptyArgs);

        // When
        Object[] result = exception.getArgs();

        // Then
        assertNotNull(result);
        assertEquals(0, result.length);
        assertNotSame(emptyArgs, result); // Should be a clone
    }
}

