/**
 * Test class for {@link ServiceException}.
 * Provides 100% test coverage for all constructors and methods in ServiceException.
 */
class ServiceExceptionTest {

    private static final String DEFAULT_ERROR_CODE = "SERVICE_ERROR";

    @Test
    void testConstructor_MessageOnly() {
        // Given
        String message = "Service operation failed";

        // When
        ServiceException exception = new ServiceException(message);

        // Then
        assertEquals(message, exception.getMessage());
        assertEquals(DEFAULT_ERROR_CODE, exception.getErrorCode());
        assertNull(exception.getCause());
        assertNull(exception.getArgs());
    }

    @Test
    void testConstructor_MessageAndErrorCode() {
        // Given
        String message = "Service operation failed";
        String errorCode = "CUSTOM_ERROR";

        // When
        ServiceException exception = new ServiceException(message, errorCode);

        // Then
        assertEquals(message, exception.getMessage());
        assertEquals(errorCode, exception.getErrorCode());
        assertNull(exception.getCause());
        assertNull(exception.getArgs());
    }

    @Test
    void testConstructor_MessageAndCause() {
        // Given
        String message = "Service operation failed";
        Throwable cause = new RuntimeException("Test cause");

        // When
        ServiceException exception = new ServiceException(message, cause);

        // Then
        assertEquals(message, exception.getMessage());
        assertEquals(DEFAULT_ERROR_CODE, exception.getErrorCode());
        assertEquals(cause, exception.getCause());
        assertNull(exception.getArgs());
    }

    @Test
    void testConstructor_MessageErrorCodeAndCause() {
        // Given
        String message = "Service operation failed";
        String errorCode = "CUSTOM_ERROR";
        Throwable cause = new RuntimeException("Test cause");

        // When
        ServiceException exception = new ServiceException(message, errorCode, cause);

        // Then
        assertEquals(message, exception.getMessage());
        assertEquals(errorCode, exception.getErrorCode());
        assertEquals(cause, exception.getCause());
        assertNull(exception.getArgs());
    }

    @Test
    void testConstructor_MessageErrorCodeCauseAndArgs() {
        // Given
        String message = "Service operation failed";
        String errorCode = "CUSTOM_ERROR";
        Throwable cause = new RuntimeException("Test cause");
        Object[] args = new Object[]{"arg1", 2, true};

        // When
        ServiceException exception = new ServiceException(message, errorCode, cause, args);

        // Then
        assertEquals(message, exception.getMessage());
        assertEquals(errorCode, exception.getErrorCode());
        assertEquals(cause, exception.getCause());
        assertNotNull(exception.getArgs());
        assertArrayEquals(args, exception.getArgs());
    }

    @Test
    void testFromException_WithAdharException() {
        // Given
        String message = "Wrapped exception";
        String originalMessage = "Original exception";
        String errorCode = "ORIGINAL_ERROR";
        Object[] args = new Object[]{"arg1", 2};
        AdharException originalException = new AdharException(originalMessage, errorCode, null, args);

        // When
        ServiceException exception = ServiceException.fromException(message, originalException);

        // Then
        assertEquals(message, exception.getMessage());
        assertEquals(errorCode, exception.getErrorCode());
        assertEquals(originalException, exception.getCause());
        assertNotNull(exception.getArgs());
        assertArrayEquals(args, exception.getArgs());
    }

    @Test
    void testFromException_WithAdharException_NullMessage() {
        // Given
        String originalMessage = "Original exception";
        String errorCode = "ORIGINAL_ERROR";
        AdharException originalException = new AdharException(originalMessage, errorCode);

        // When
        ServiceException exception = ServiceException.fromException(null, originalException);

        // Then
        assertEquals(originalMessage, exception.getMessage());
        assertEquals(errorCode, exception.getErrorCode());
        assertEquals(originalException, exception.getCause());
    }

    @Test
    void testFromException_WithNonAdharException() {
        // Given
        String message = "Wrapped exception";
        String originalMessage = "Original exception";
        RuntimeException originalException = new RuntimeException(originalMessage);

        // When
        ServiceException exception = ServiceException.fromException(message, originalException);

        // Then
        assertEquals(message, exception.getMessage());
        assertEquals(DEFAULT_ERROR_CODE, exception.getErrorCode());
        assertEquals(originalException, exception.getCause());
        assertNull(exception.getArgs());
    }

    @Test
    void testFromException_WithNonAdharException_NullMessage() {
        // Given
        String originalMessage = "Original exception";
        RuntimeException originalException = new RuntimeException(originalMessage);

        // When
        ServiceException exception = ServiceException.fromException(null, originalException);

        // Then
        assertEquals(originalMessage, exception.getMessage());
        assertEquals(DEFAULT_ERROR_CODE, exception.getErrorCode());
        assertEquals(originalException, exception.getCause());
        assertNull(exception.getArgs());
    }
}

