package com.example.adhar.commons.service;

import com.adhar.kit.commons.exception.ResourceNotFoundException;
import com.adhar.kit.commons.service.BaseService;
import com.adhar.kit.commons.exception.ServiceException;
import com.adhar.kit.commons.exception.ValidationException;
import com.adhar.kit.commons.model.PagedResult;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

import java.util.Arrays;
import java.util.List;
import java.util.Optional;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Test class for {@link BaseService}.
 */
class BaseServiceTest {

    private TestService service;

    @BeforeEach
    void setUp() {
        service = new TestService();
    }

    @Test
    void testExecuteWithExceptionHandling_Success() {
        // Given
        String expected = "success";

        // When
        String result = service.testExecuteWithExceptionHandling(() -> expected, "Error message");

        // Then
        assertEquals(expected, result);
    }

    @Test
    void testExecuteWithExceptionHandling_ResourceNotFoundException() {
        // Given
        ResourceNotFoundException expectedException = new ResourceNotFoundException("Resource not found");

        // When & Then
        ResourceNotFoundException exception = assertThrows(ResourceNotFoundException.class, () -> {
            service.testExecuteWithExceptionHandling(() -> {
                throw expectedException;
            }, "Error message");
        });

        assertEquals(expectedException, exception);
    }

    @Test
    void testExecuteWithExceptionHandling_ValidationException() {
        // Given
        ValidationException expectedException = new ValidationException("Validation failed");

        // When & Then
        ValidationException exception = assertThrows(ValidationException.class, () -> {
            service.testExecuteWithExceptionHandling(() -> {
                throw expectedException;
            }, "Error message");
        });

        assertEquals(expectedException, exception);
    }

    @Test
    void testExecuteWithExceptionHandling_OtherException() {
        // Given
        RuntimeException expectedException = new RuntimeException("Some error");
        String errorMessage = "Error message";

        // When & Then
        ServiceException exception = assertThrows(ServiceException.class, () -> {
            service.testExecuteWithExceptionHandling(() -> {
                throw expectedException;
            }, errorMessage);
        });

        assertEquals(errorMessage, exception.getMessage());
        assertEquals(expectedException, exception.getCause());
    }

    @Test
    void testExecuteWithExceptionHandling_Void_Success() {
        // When & Then
        assertDoesNotThrow(() -> {
            service.testExecuteWithExceptionHandling(() -> {
                // Do nothing
            }, "Error message");
        });
    }

    @Test
    void testExecuteWithExceptionHandling_Void_ResourceNotFoundException() {
        // Given
        ResourceNotFoundException expectedException = new ResourceNotFoundException("Resource not found");

        // When & Then
        ResourceNotFoundException exception = assertThrows(ResourceNotFoundException.class, () -> {
            service.testExecuteWithExceptionHandling(() -> {
                throw expectedException;
            }, "Error message");
        });

        assertEquals(expectedException, exception);
    }

    @Test
    void testExecuteWithExceptionHandling_Void_ValidationException() {
        // Given
        ValidationException expectedException = new ValidationException("Validation failed");

        // When & Then
        ValidationException exception = assertThrows(ValidationException.class, () -> {
            service.testExecuteWithExceptionHandling(() -> {
                throw expectedException;
            }, "Error message");
        });

        assertEquals(expectedException, exception);
    }

    @Test
    void testExecuteWithExceptionHandling_Void_OtherException() {
        // Given
        RuntimeException expectedException = new RuntimeException("Some error");
        String errorMessage = "Error message";

        // When & Then
        ServiceException exception = assertThrows(ServiceException.class, () -> {
            service.testExecuteWithExceptionHandling(() -> {
                throw expectedException;
            }, errorMessage);
        });

        assertEquals(errorMessage, exception.getMessage());
        assertEquals(expectedException, exception.getCause());
    }

    @Test
    void testGetOrThrow_Present() {
        // Given
        String entity = "Test Entity";
        Optional<String> optionalEntity = Optional.of(entity);
        String resourceType = "TestResource";
        Long id = 1L;

        // When
        String result = service.testGetOrThrow(optionalEntity, resourceType, id.toString());

        // Then
        assertEquals(entity, result);
    }

    @Test
    void testGetOrThrow_Empty() {
        // Given
        Optional<String> optionalEntity = Optional.empty();
        String resourceType = "TestResource";
        Long id = 1L;

        // When & Then
        ResourceNotFoundException exception = assertThrows(ResourceNotFoundException.class, () -> {
            service.testGetOrThrow(optionalEntity, resourceType, id.toString());
        });

        assertEquals("TestResource with ID '1' not found", exception.getMessage());
    }

    @Test
    void testValidateCondition_True() {
        // When & Then
        assertDoesNotThrow(() -> {
            service.testValidateCondition(true, "field", "error message");
        });
    }

    @Test
    void testValidateCondition_False() {
        // Given
        String field = "field";
        String errorMessage = "error message";

        // When & Then
        ValidationException exception = assertThrows(ValidationException.class, () -> {
            service.testValidateCondition(false, field, errorMessage);
        });

        assertEquals("Validation failed", exception.getMessage());
        assertEquals(1, exception.getValidationErrors().size());
        assertTrue(exception.getValidationErrors().containsKey(field));
        assertEquals(errorMessage, exception.getValidationErrors().get(field).get(0));
