package com.example.adhar.commons.util;

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

import java.time.Instant;
import java.time.LocalDate;
import java.time.LocalDateTime;
import java.time.ZoneId;
import java.time.ZonedDateTime;
import java.time.format.DateTimeParseException;

/**
 * Test class for {@link DateUtils}.
 * Provides 100% test coverage for all methods in DateUtils.
 */
class DateUtilsTest {

    @Test
    void testFormatDate_Default() {
        // Test with null date
        assertNull(DateUtils.formatDate((LocalDate) null));

        // Test with valid date
        LocalDate date = LocalDate.of(2023, 1, 15);
        assertEquals("2023-01-15", DateUtils.formatDate(date));
    }

    @Test
    void testFormatDate_CustomPattern() {
        // Test with null date
        assertNull(DateUtils.formatDate((LocalDate) null, "MM/dd/yyyy"));

        // Test with valid date and pattern
        LocalDate date = LocalDate.of(2023, 1, 15);
        assertEquals("01/15/2023", DateUtils.formatDate(date, "MM/dd/yyyy"));
    }

    @Test
    void testFormatDateTime_Default() {
        // Test with null date time
        assertNull(DateUtils.formatDateTime((LocalDateTime) null));

        // Test with valid date time
        LocalDateTime dateTime = LocalDateTime.of(2023, 1, 15, 10, 30, 45);
        assertEquals("2023-01-15T10:30:45", DateUtils.formatDateTime(dateTime));
    }

    @Test
    void testFormatDateTime_CustomPattern() {
        // Test with null date time
        assertNull(DateUtils.formatDateTime((LocalDateTime) null, "MM/dd/yyyy HH:mm"));

        // Test with valid date time and pattern
        LocalDateTime dateTime = LocalDateTime.of(2023, 1, 15, 10, 30, 45);
        assertEquals("01/15/2023 10:30", DateUtils.formatDateTime(dateTime, "MM/dd/yyyy HH:mm"));
    }

    @Test
    void testParseDate_Default() {
        // Test with null string
        assertNull(DateUtils.parseDate(null));

        // Test with empty string
        assertNull(DateUtils.parseDate(""));

        // Test with blank string
        assertNull(DateUtils.parseDate("   "));

        // Test with valid date string
        LocalDate expected = LocalDate.of(2023, 1, 15);
        assertEquals(expected, DateUtils.parseDate("2023-01-15"));

        // Test with invalid date string
        assertThrows(DateTimeParseException.class, () -> DateUtils.parseDate("invalid-date"));
    }

    @Test
    void testParseDate_CustomPattern() {
        // Test with null string
        assertNull(DateUtils.parseDate(null, "MM/dd/yyyy"));

        // Test with empty string
        assertNull(DateUtils.parseDate("", "MM/dd/yyyy"));

        // Test with blank string
        assertNull(DateUtils.parseDate("   ", "MM/dd/yyyy"));

        // Test with valid date string and pattern
        LocalDate expected = LocalDate.of(2023, 1, 15);
        assertEquals(expected, DateUtils.parseDate("01/15/2023", "MM/dd/yyyy"));

        // Test with invalid date string
        assertThrows(DateTimeParseException.class, () -> DateUtils.parseDate("invalid-date", "MM/dd/yyyy"));
    }

    @Test
    void testParseDateTime_Default() {
        // Test with null string
        assertNull(DateUtils.parseDateTime(null));

        // Test with empty string
        assertNull(DateUtils.parseDateTime(""));

        // Test with blank string
        assertNull(DateUtils.parseDateTime("   "));

        // Test with valid date time string
        LocalDateTime expected = LocalDateTime.of(2023, 1, 15, 10, 30, 45);
        assertEquals(expected, DateUtils.parseDateTime("2023-01-15T10:30:45"));

        // Test with invalid date time string
        assertThrows(DateTimeParseException.class, () -> DateUtils.parseDateTime("invalid-datetime"));
    }

    @Test
    void testParseDateTime_CustomPattern() {
        // Test with null string
        assertNull(DateUtils.parseDateTime(null, "MM/dd/yyyy HH:mm"));

        // Test with empty string
        assertNull(DateUtils.parseDateTime("", "MM/dd/yyyy HH:mm"));

        // Test with blank string
        assertNull(DateUtils.parseDateTime("   ", "MM/dd/yyyy HH:mm"));

        // Test with valid date time string and pattern
        LocalDateTime expected = LocalDateTime.of(2023, 1, 15, 10, 30);
        assertEquals(expected, DateUtils.parseDateTime("01/15/2023 10:30", "MM/dd/yyyy HH:mm"));

        // Test with invalid date time string
        assertThrows(DateTimeParseException.class, () -> DateUtils.parseDateTime("invalid-datetime", "MM/dd/yyyy HH:mm"));
    }

    @Test
    void testToInstant() {
        // Test with null date time
        assertNull(DateUtils.toInstant(null));

        // Test with valid date time
        LocalDateTime dateTime = LocalDateTime.of(2023, 1, 15, 10, 30, 45);
        Instant expected = dateTime.atZone(ZoneId.systemDefault()).toInstant();
        assertEquals(expected, DateUtils.toInstant(dateTime));
    }

    @Test
    void testFromInstant() {
        // Test with null instant
        assertNull(DateUtils.fromInstant(null));

        // Test with valid instant
        LocalDateTime dateTime = LocalDateTime.of(2023, 1, 15, 10, 30, 45);
        Instant instant = dateTime.atZone(ZoneId.systemDefault()).toInstant();
        assertEquals(dateTime, DateUtils.fromInstant(instant));
    }

    @Test
    void testNow() {
        // Test that now() returns a non-null value
        assertNotNull(DateUtils.now());

        // Test that now() returns a value close to the current time
        LocalDateTime now = LocalDateTime.now();
        LocalDateTime result = DateUtils.now();
        assertTrue(Math.abs(now.until(result, java.time.temporal.ChronoUnit.SECONDS)) < 2);
    }

    @Test
    void testToday() {
        // Test that today() returns a non-null value
        assertNotNull(DateUtils.today());

        // Test that today() returns the current date
        assertEquals(LocalDate.now(), DateUtils.today());
    }

    @Test
    void testDaysBetween() {
        // Test with valid dates
        LocalDate startDate = LocalDate.of(2023, 1, 15);
        LocalDate endDate = LocalDate.of(2023, 1, 20);
        assertEquals(5, DateUtils.daysBetween(startDate, endDate));

        // Test with same date
        assertEquals(0, DateUtils.daysBetween(startDate, startDate));

        // Test with end date before start date
        assertEquals(-5, DateUtils.daysBetween(endDate, startDate));

        // Test with null dates
        assertThrows(IllegalArgumentException.class, () -> DateUtils.daysBetween(null, endDate));
        assertThrows(IllegalArgumentException.class, () -> DateUtils.daysBetween(startDate, null));
        assertThrows(IllegalArgumentException.class, () -> DateUtils.daysBetween(null, null));
    }

    @Test
    void testToZonedDateTime() {
        // Test with null date time
        assertNull(DateUtils.toZonedDateTime(null, ZoneId.of("UTC")));

        // Test with valid date time and zone ID
        LocalDateTime dateTime = LocalDateTime.of(2023, 1, 15, 10, 30, 45);
        ZoneId zoneId = ZoneId.of("UTC");
        ZonedDateTime expected = dateTime.atZone(zoneId);
        assertEquals(expected, DateUtils.toZonedDateTime(dateTime, zoneId));

        // Test with valid date time and null zone ID (should use system default)
        ZonedDateTime expectedDefault = dateTime.atZone(ZoneId.systemDefault());
        assertEquals(expectedDefault, DateUtils.toZonedDateTime(dateTime, null));
    }
}

