    void testDaysBetween() {
        // Test with valid dates
        LocalDate startDate = LocalDate.of(2023, 1, 15);
        LocalDate endDate = LocalDate.of(2023, 1, 20);
        assertEquals(5, DateUtils.daysBetween(startDate, endDate));

        // Test with same date
        assertEquals(0, DateUtils.daysBetween(startDate, startDate));

        // Test with end date before start date
        assertEquals(-5, DateUtils.daysBetween(endDate, startDate));

        // Test with null dates
        assertThrows(IllegalArgumentException.class, () -> DateUtils.daysBetween(null, endDate));
        assertThrows(IllegalArgumentException.class, () -> DateUtils.daysBetween(startDate, null));
        assertThrows(IllegalArgumentException.class, () -> DateUtils.daysBetween(null, null));
    }

    @Test
    void testToZonedDateTime() {
        // Test with null date time
        assertNull(DateUtils.toZonedDateTime(null, ZoneId.of("UTC")));

        // Test with valid date time and zone ID
        LocalDateTime dateTime = LocalDateTime.of(2023, 1, 15, 10, 30, 45);
        ZoneId zoneId = ZoneId.of("UTC");
        ZonedDateTime expected = dateTime.atZone(zoneId);
        assertEquals(expected, DateUtils.toZonedDateTime(dateTime, zoneId));

        // Test with valid date time and null zone ID (should use system default)
        ZonedDateTime expectedDefault = dateTime.atZone(ZoneId.systemDefault());
        assertEquals(expectedDefault, DateUtils.toZonedDateTime(dateTime, null));
    }
}

package com.example.adhar.commons.util;

import com.adhar.kit.commons.util.StringUtils;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

/**
 * Test class for {@link StringUtils}.
 * Provides 100% test coverage for all methods in StringUtils.
 */
class StringUtilsTest {

    @Test
    void testIsEmpty() {
        // Test with null string
        assertTrue(StringUtils.isEmpty(null));

        // Test with empty string
        assertTrue(StringUtils.isEmpty(""));

        // Test with whitespace string
        assertFalse(StringUtils.isEmpty(" "));

        // Test with non-empty string
        assertFalse(StringUtils.isEmpty("test"));
    }

    @Test
    void testIsBlank() {
        // Test with null string
        assertTrue(StringUtils.isBlank(null));

        // Test with empty string
        assertTrue(StringUtils.isBlank(""));

        // Test with whitespace string
        assertTrue(StringUtils.isBlank(" "));
        assertTrue(StringUtils.isBlank("\t"));
        assertTrue(StringUtils.isBlank("\n"));
        assertTrue(StringUtils.isBlank("  \t  \n  "));

        // Test with non-blank string
        assertFalse(StringUtils.isBlank("test"));
        assertFalse(StringUtils.isBlank(" test "));
    }

    @Test
    void testDefaultIfNull() {
        // Test with null string
        assertEquals("", StringUtils.defaultIfNull(null));

        // Test with empty string
        assertEquals("", StringUtils.defaultIfNull(""));

        // Test with non-empty string
        assertEquals("test", StringUtils.defaultIfNull("test"));
    }

    @Test
    void testDefaultIfEmpty() {
        String defaultValue = "default";

        // Test with null string
        assertEquals(defaultValue, StringUtils.defaultIfEmpty(null, defaultValue));

        // Test with empty string
        assertEquals(defaultValue, StringUtils.defaultIfEmpty("", defaultValue));

        // Test with non-empty string
        assertEquals("test", StringUtils.defaultIfEmpty("test", defaultValue));

        // Test with null default value
        assertEquals("test", StringUtils.defaultIfEmpty("test", null));
        assertNull(StringUtils.defaultIfEmpty(null, null));
    }

    @Test
    void testTruncate() {
        // Test with null string
        assertNull(StringUtils.truncate(null, 5));

        // Test with string shorter than max length
        assertEquals("test", StringUtils.truncate("test", 5));

        // Test with string equal to max length
        assertEquals("test", StringUtils.truncate("test", 4));

        // Test with string longer than max length
        assertEquals("test", StringUtils.truncate("testing", 4));

        // Test with zero max length
        assertEquals("", StringUtils.truncate("test", 0));

        // Test with negative max length (should be treated as zero)
        assertEquals("", StringUtils.truncate("test", -1));
    }

    @Test
    void testMask() {
        // Test with null string
        assertNull(StringUtils.mask(null));

        // Test with empty string
        assertEquals("", StringUtils.mask(""));

        // Test with single character
        assertEquals("a", StringUtils.mask("a"));

        // Test with two characters
        assertEquals("ab", StringUtils.mask("ab"));

        // Test with three characters
        assertEquals("a*c", StringUtils.mask("abc"));

        // Test with longer string
        assertEquals("h****o", StringUtils.mask("hello"));
        assertEquals("t*******t", StringUtils.mask("test1234t"));

        // Test with special characters
        assertEquals("!***$", StringUtils.mask("!abc$"));
    }
}

